1	// Tensor-core FlashAttention-style forward kernel (wmma m16n16k16, BF16).
2	// One block per (query tile, batch*head); BLOCK_M=64 query rows, 4 warps
3	// (16 rows each); K/V tiles of BLOCK_N=64 staged via cp.async double buffer.
4	// Supports MHA and GQA (kv_heads <= heads), causal and non-causal, any S.
5	#include <torch/extension.h>
6	#include <ATen/cuda/CUDAContext.h>
7	#include <c10/cuda/CUDAGuard.h>
8	#include <cuda_runtime.h>
9	#include <cuda_bf16.h>
10	#include <mma.h>
11	#include <math.h>
12	
13	namespace {
14	
15	using namespace nvcuda;
16	
17	constexpr int BLOCK_M = 64;
18	constexpr int BLOCK_N = 64;
19	constexpr int HEAD_DIM = 128;
20	constexpr int NUM_WARPS = 4;
21	constexpr int NUM_THREADS = NUM_WARPS * 32;
22	constexpr int PADDED_D = HEAD_DIM + 8;         // pad rows to avoid bank conflicts
23	constexpr int P_COLS = BLOCK_N + 8;
24	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;
25	constexpr int O_ELEMS = BLOCK_M * PADDED_D;
26	constexpr int P_SMEM = NUM_WARPS * 16 * P_COLS * 2;
27	constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2 + O_ELEMS * 2 + P_SMEM;
28	
29	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
30	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
31	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
32	}
33	__device__ __forceinline__ void cp_async_commit() { asm volatile("cp.async.commit_group;\n"); }
34	template<int N> __device__ __forceinline__ void cp_async_wait() {
35	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
36	}
37	
38	__device__ __forceinline__ void load_tile(const __nv_bfloat16* src,
39	                                          __nv_bfloat16* dst, int row0,
40	                                          int seq_len, bool zero_fill) {
41	    constexpr int CHUNKS = BLOCK_N * HEAD_DIM / 8;
42	    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
43	        const int row = i / (HEAD_DIM / 8), col8 = i % (HEAD_DIM / 8);
44	        const int grow = row0 + row;
45	        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
46	        if (grow < seq_len) cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
47	        else if (zero_fill) *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
48	    }
49	}
50	
51	__device__ __forceinline__ float warp_max4(float v) {
52	    for (int off = 1; off < 4; off <<= 1) v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
53	    return v;
54	}
55	__device__ __forceinline__ float warp_sum4(float v) {
56	    for (int off = 1; off < 4; off <<= 1) v += __shfl_xor_sync(0xffffffffu, v, off);
57	    return v;
58	}
59	
60	__global__ void __launch_bounds__(NUM_THREADS, 1)
61	attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
62	                     const __nv_bfloat16* __restrict__ k,
63	                     const __nv_bfloat16* __restrict__ v,
64	                     __nv_bfloat16* __restrict__ out,
65	                     int seq_len, int kv_heads, int heads, float scale, bool causal)
66	{
67	    extern __shared__ char smem[];
68	    __nv_bfloat16* sK0 = reinterpret_cast<__nv_bfloat16*>(smem);
69	    __nv_bfloat16* sV0 = sK0 + TILE_ELEMS;
70	    __nv_bfloat16* sK1 = sV0 + TILE_ELEMS;
71	    __nv_bfloat16* sV1 = sK1 + TILE_ELEMS;
72	    __nv_bfloat16* sP = sV1 + TILE_ELEMS;
73	    __nv_bfloat16* sQO = sP + NUM_WARPS * 16 * P_COLS;
74	
75	    const int m_tile = blockIdx.x, bh = blockIdx.y;
76	    const int b = bh / heads;                 // batch index
77	    const int qh = bh % heads;                // query head within batch
78	    const int kv_head = qh / (heads / kv_heads);   // GQA: kv head serving this q head
79	    const long long qbase = (long long)bh * seq_len * HEAD_DIM;
80	    const long long kvbase = (long long)(b * kv_heads + kv_head) * seq_len * HEAD_DIM;
81	    const int warp = threadIdx.x / 32, lane = threadIdx.x % 32;
82	    const int m0 = m_tile * BLOCK_M + warp * 16;
83	    const int m0b = m_tile * BLOCK_M;
84	
