60	__global__ void __launch_bounds__(NUM_THREADS, 1)
61	attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
62	                     const __nv_bfloat16* __restrict__ k,
63	                     const __nv_bfloat16* __restrict__ v,
64	                     __nv_bfloat16* __restrict__ out,
65	                     int seq_len, int kv_heads, int heads, float scale, bool causal)
66	{
67	    extern __shared__ char smem[];
68	    __nv_bfloat16* sK0 = reinterpret_cast<__nv_bfloat16*>(smem);
69	    __nv_bfloat16* sV0 = sK0 + TILE_ELEMS;
70	    __nv_bfloat16* sK1 = sV0 + TILE_ELEMS;
71	    __nv_bfloat16* sV1 = sK1 + TILE_ELEMS;
72	    __nv_bfloat16* sP = sV1 + TILE_ELEMS;
73	    __nv_bfloat16* sQO = sP + NUM_WARPS * 16 * P_COLS;
74	
75	    const int m_tile = blockIdx.x, bh = blockIdx.y;
76	    const int b = bh / heads;                 // batch index
77	    const int qh = bh % heads;                // query head within batch
78	    const int kv_head = qh / (heads / kv_heads);   // GQA: kv head serving this q head
79	    const long long qbase = (long long)bh * seq_len * HEAD_DIM;
80	    const long long kvbase = (long long)(b * kv_heads + kv_head) * seq_len * HEAD_DIM;
81	    const int warp = threadIdx.x / 32, lane = threadIdx.x % 32;
82	    const int m0 = m_tile * BLOCK_M + warp * 16;
83	    const int m0b = m_tile * BLOCK_M;
84	
85	    load_tile(q + qbase, sQO, m0b, seq_len, true);
86	    cp_async_commit(); cp_async_wait<0>(); __syncthreads();
87	
88	    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> q_frag[8];
89	    for (int kt = 0; kt < 8; ++kt)
90	        wmma::load_matrix_sync(q_frag[kt], sQO + warp * 16 * PADDED_D + kt * 16, PADDED_D);
91	
92	    wmma::fragment<wmma::accumulator, 16, 16, 16, float> s_frag[2];
93	    wmma::fragment<wmma::accumulator, 16, 16, 16, float> o_frag[8];
94	    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> k_frag;
95	    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> v_frag;
96	    for (int i = 0; i < 8; ++i) wmma::fill_fragment(o_frag[i], 0.f);
97	
98	    float m_prev[2] = {-INFINITY, -INFINITY};
99	    float l_prev[2] = {0.f, 0.f};
100	
101	    const int n_tiles_total = (seq_len + BLOCK_N - 1) / BLOCK_N;
102	    const int n_tiles_block = causal ? min(n_tiles_total, (m0b + BLOCK_M - 1) / BLOCK_N + 1)
103	                                     : n_tiles_total;
104	    if (n_tiles_block > 0) {
105	        load_tile(k + kvbase, sK0, 0, seq_len, true);
106	        load_tile(v + kvbase, sV0, 0, seq_len, true);
107	        cp_async_commit();
108	    }
109	
110	    for (int nt = 0; nt < n_tiles_block; ++nt) {
111	        const int buf = nt & 1;
112	        __nv_bfloat16* sK = buf ? sK1 : sK0;
113	        __nv_bfloat16* sV = buf ? sV1 : sV0;
114	        if (nt + 1 < n_tiles_block) {
115	            load_tile(k + kvbase, buf ? sK0 : sK1, (nt + 1) * BLOCK_N, seq_len, true);
116	            load_tile(v + kvbase, buf ? sV0 : sV1, (nt + 1) * BLOCK_N, seq_len, true);
117	            cp_async_commit();
118	        }
119	        if (nt + 1 < n_tiles_block) cp_async_wait<1>(); else cp_async_wait<0>();

120	        __syncthreads();
121	        const int kv0 = nt * BLOCK_N;
122	
123	        for (int i = 0; i < 2; ++i) {
124	            const int kvc = kv0 + 16 * i;
125	            const bool full_mask = causal && (kvc > m0 + 15);
126	            const bool may_mask = causal && !full_mask && (kvc + 15 >= m0) && (kvc <= m0 + 15);
127	            const bool kv_oob = (kvc + 15 >= seq_len);   // last tile may extend past seq_len
128	            __nv_bfloat16* Pw = sP + warp * (16 * P_COLS) + 16 * i;
129	            for (int j = 0; j < 8; ++j) s_frag[i].x[j] = 0.f;
130	            if (full_mask) {
131	                for (int j = 0; j < 8; ++j) {
132	                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
133	                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
134	                    Pw[rr * P_COLS + cc] = __float2bfloat16(0.f);
135	                }
136	                continue;
137	            }
138	            for (int kt = 0; kt < 8; ++kt) {
139	                wmma::load_matrix_sync(k_frag, sK + (16 * i) * PADDED_D + kt * 16, PADDED_D);
140	                wmma::mma_sync(s_frag[i], q_frag[kt], k_frag, s_frag[i]);
141	            }
142	            for (int j = 0; j < 8; ++j) s_frag[i].x[j] *= scale;
143	            if (may_mask || kv_oob) {
144	                for (int j = 0; j < 8; ++j) {
145	                    const int rr = ((j & 2) ? 8 : 0) + lane / 4;
146	                    const int cc = 2 * (lane % 4) + (j & 1) + ((j & 4) ? 8 : 0);
147	                    if ((causal && kvc + cc > m0 + rr) || (kvc + cc >= seq_len))
148	                        s_frag[i].x[j] = -INFINITY;
149	                }
150	            }
151	            float tm0 = fmaxf(fmaxf(s_frag[i].x[0], s_frag[i].x[1]),
152	                              fmaxf(s_frag[i].x[4], s_frag[i].x[5]));
153	            float tm1 = fmaxf(fmaxf(s_frag[i].x[2], s_frag[i].x[3]),
154	                              fmaxf(s_frag[i].x[6], s_frag[i].x[7]));
155	            tm0 = warp_max4(tm0); tm1 = warp_max4(tm1);
156	            const float mn0 = fmaxf(m_prev[0], tm0), mn1 = fmaxf(m_prev[1], tm1);
157	            const float corr0 = __expf(m_prev[0] - mn0), corr1 = __expf(m_prev[1] - mn1);
158	            for (int o = 0; o < 8; ++o)
159	                for (int j = 0; j < 8; ++j)
160	                    o_frag[o].x[j] *= ((j & 2) ? corr1 : corr0);
161	            float ps0 = 0.f, ps1 = 0.f;
162	            for (int j = 0; j < 8; ++j) {
163	                const float p = __expf(s_frag[i].x[j] - ((j & 2) ? mn1 : mn0));
164	                s_frag[i].x[j] = p;
165	                if (j & 2) ps1 += p; else ps0 += p;
